270	interface ScenarioState {
271	  readonly results: readonly StepResult[];
272	  readonly remainingCaps: readonly number[];
273	}
274	
275	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
276	  results: [],
