287	const stateAfterQuote = (
288	  state: ScenarioState,
289	  result: QuoteResult,
290	): ScenarioState => ({ ...state, results: [...state.results, result] });
291	
292	const stateAfterClaim = (
293	  state: ScenarioState,
294	  step: ClaimStep,
295	  result: ClaimResult,
296	): ScenarioState => ({
297	  results: [...state.results, result],
298	  remainingCaps: capsAfterClaim(
299	    state.remainingCaps,
300	    step.policy,
301	    result.remainingCap,
302	  ),
303	});
