312	            state,
313	            quoteResultOf(
314	              step,
315	              scenario.customer,
316	              quoteStepsBefore(scenario.steps, stepIndex),
317	            ),
318	          )
319	        : stateAfterClaim(
320	            state,
321	            step,
322	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
323	          ),
324	    initialStateOf(policies),
325	  );
326	
327	  return { results };
328	};
